// CSD_RATIONALE_BEGIN
// This strategy tracks the full generated output, whether generation is currently
// inside a constrained arithmetic span, and the current constrained contents
// between << and >>. Outside constrained spans it generates ordinary explanatory
// text, but after some free-form progress it opportunistically opens a constrained
// span so arithmetic can be written explicitly. Inside a constrained span it uses
// parser-guided constrained decoding, preferring valid arithmetic continuations;
// if the constrained prefix appears to be a dead end, it rolls back to a valid
// prefix and may exit the span if repair leaves nothing usable.
// These state variables support valid generation because the full output retains
// delimiters, while the constrained-only state stores exactly the arithmetic
// substring that must satisfy parser validity. The suffix relationship between
// generated and currentConstrainedOut is maintained so helper preconditions for
// append, close, and rollback remain provable throughout decoding.
// CSD_RATIONALE_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant exists suffix: Prefix :: generated == generatedPrefix + suffix
  invariant |generated| <= |generatedPrefix| + steps
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant cost == 0
  invariant helpers.cost <= steps
  decreases maxSteps - steps
